function [ap] = kp2ap(kp)
%KP2AP  kp2ap (atmos.spaceweather): the nearest node of the standard table, Kp clamped to [0, 9].
%   kp: real[1] (passed a plain number)
%   returns ap: real[1] (passed a plain number)
%   Generated by tools/pcode.py from the pseudocode (trinetra-pcode/2); do not edit.
    ap = 0;
    if isnan(kp)
        ap = NaN;
    else
        ap = asils.models.swindex.kp_ap_nearest(true, asils.pc.fmax(asils.pc.fmin(kp, 9), 0));
    end
end
